  "deliberation_status": {
    "round": 4,
    "total_rounds": 8,
    "unanimous_inclusions": ["Gragas", "Vi", "Jarvan", "Fizz", "Pyke", "Sejuani", "Shen", "Tryndamere", "Urgot", "Yone", "Camille"],
    "unanimous_exclusions": ["LeBlanc", "Galio", "Kayn", "Ornn", "Poppy", "Rakan", "Rell", "Tristana", "Zac", "Renekton", "Nidalee", "Fiora", "Corki", "BelVeth"],
    "split_candidate": "Riven (Q3)",
    "vote_breakdown": {
      "11_champions (Exclude Riven)": ["C2", "C3", "C4", "C6", "C8", "C10", "C11", "C12"],
      "12_champions (Include Riven)": ["C1", "C5", "C7", "C9", "C13", "C14"]
    }
  },
  "substantive_analysis_of_riven_dispute": {
    "pro_riven_stance": "Argues that Q3's knockup is an endpoint event tied to Riven's model, claiming a sub-frame pre-impact buffer exists where Flash can execute at the exact transition frame before the impact packet instantiates, relocating the CC.",
    "engine_reality_and_refutation": [
      "Spell State Hierarchy & Queue Resolution: In the League engine, command buffer evaluation is gated by `CanCastSummonerSpells`. This flag is hard-locked to FALSE across the startup, leap interpolation, and impact packet instantiation of Q3.",
      "No Preemption: Buffered inputs cannot preempt an active atomic spell script event. The knockup packet is generated at the end of the leap in Phase 3; the lockout flag clears only in Phase 4 (backswing/recovery). Therefore, the queued Flash always executes strictly post-impact.",
      "Empirical Outcome: Executing true `Q3 -> Flash` (at any timing, including the final frame before landing) leaves the knockup at the initial landing coordinates (Dummy A takes CC/damage; Dummy B at Flash destination takes 0).",
      "False Equivalence: Unlike Urgot E (Flash permitted during 0.45s windup), Yone Q3 / Shen E (active collision volume mid-dash with Flash enabled), or Fizz E2 (Flash permitted during descent), Riven has zero active-collision frames and zero summoner-enabled frames prior to impact.",
      "Confusion Source: Pro-Riven proponents are conflating `Flash -> Q3` or `E -> Flash -> Q3` (Flash-Dash) with `Q3 -> Flash` (Dash-Flash)."
    ]
  },
  "strategy_moving_forward": {
    "stance": "Strictly maintain 11 champions: Gragas, Vi, Jarvan, Fizz, Pyke, Sejuani, Shen, Tryndamere, Urgot, Yone, Camille.",
    "tactics": "Hold the line firmly against Camp Pro-Riven. The technical breakdown of the event pipeline (Impact packet instantiation in Phase 3 strictly preceding buffer evaluation upon lockout clearing in Phase 4) is insurmountable. Continue emphasizing that Dummy B takes 0 damage and 0 CC in an isolated Q3->Flash test."
  }
}

